"""Measure the complete independent audit process, including startup and final writes."""
import argparse,hashlib,json,resource,subprocess,sys,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--study',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();study=Path(a.study).resolve();output=Path(a.output).resolve();outer=output.with_name(output.stem+'_budget.json');assert not output.exists() and not outer.exists();start=time.monotonic();before=resource.getrusage(resource.RUSAGE_CHILDREN)
 def limit():resource.setrlimit(resource.RLIMIT_CPU,(9,10))
 result=subprocess.run([sys.executable,'-u','-m','research.invariant_families_v1.audit_overlap','--study',str(study),'--output',str(output)],cwd=ROOT,preexec_fn=limit,capture_output=True,timeout=110);after=resource.getrusage(resource.RUSAGE_CHILDREN);child=after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime;output.with_suffix('.stdout.txt').write_bytes(result.stdout);output.with_suffix('.stderr.txt').write_bytes(result.stderr);producer=json.loads((study/'outer_budget.json').read_text());certificate=json.loads(output.read_text()) if output.exists() else {};cpu=child+time.process_time();elapsed=time.monotonic()-start;report=dict(passed=result.returncode==0 and certificate.get('passed') and cpu<=10 and cpu+producer['whole_producer_cpu_seconds']<=30,returncode=result.returncode,whole_audit_cpu_seconds=cpu,child_audit_cpu_seconds=child,audit_wall_seconds=elapsed,audit_share_seconds=10,dedicated_producer_plus_audit_cpu_seconds=cpu+producer['whole_producer_cpu_seconds'],dedicated_workflow_total_limit_seconds=30,producer_receipt_sha256=hashlib.sha256((study/'outer_budget.json').read_bytes()).hexdigest(),audit_certificate_sha256=hashlib.sha256(output.read_bytes()).hexdigest() if output.exists() else None,wrapper_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='Dedicated producer and independent-auditor processes include startup, all work and final child writes. Earlier exploratory/static preflight checks are separate receipts; no native study was rerun.');outer.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n');print(json.dumps(report));raise SystemExit(0 if report['passed'] else 1)
if __name__=='__main__':main()
